    [9] = {
      beijing = 4908,
      dialog = 3,
      music = "48_Quiet_Daily",
      renwu = "npc",
      sentence = "He was always sitting by the window alone, playing a song... always seeing the flow of pedestrians and cars wane, and that coffee shop close up for the night.",
